  this.element=element;this.asset=asset;this.cast=cast;this.mode=mode;this.language=language;this.onPreference=onPreference;this.preferences={music:false,effects:false,...preferences};this.dead=false;this.loaded=false;this.hidden=false;this.manualPaused=false;
  this.clock=new PlaybackClock(mode==='ambient'?4000:asset.durationMs,onFinish,mode==='ambient');this.beats=sceneBeats(asset,cast,language,optionTitle);if(mode==='ambient')this.beats=[{...this.beats.at(-1),at:0}];this.reduce=globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches||preferences.reducedMotion===true;
  const tr=(en,zh)=>language==='zh'?zh:en;
  element.innerHTML=`<div class="incident-player ${this.reduce?'reduced-motion':''}" data-mode="${mode}" data-scene="${E(asset.id)}" data-beat="enter"><div class="animation-viewport">${sceneArtwork(asset,cast,{twins,babies,optionId:asset.outcomeId})}<div class="animation-loading" role="status">${tr('Preparing your scene…','正在准备场景……')}</div><div class="animation-subtitles" aria-live="off"><span class="speaker"></span><p></p></div></div><div class="playback-bar"><span class="playback-state" role="status">${tr('Loading','载入中')}</span><div class="playback-track" aria-hidden="true"><i></i></div><button type="button" data-playback="pause">${tr('Pause','暂停')}</button><button type="button" data-playback="replay">${tr('Replay','重播')}</button><button type="button" data-playback="skip" class="playback-skip">${mode==='ambient'?tr('End loop','结束循环'):tr('Skip scene','跳过场景')}</button></div><details class="sound-options"><summary>${tr('Sound & motion · muted by default','声音与动态 · 默认静音')}</summary><label><input type="checkbox" data-sound="music" ${this.preferences.music?'checked':''}>${tr('Original ambient tones','原创环境音调')}</label><label><input type="checkbox" data-sound="effects" ${this.preferences.effects?'checked':''}>${tr('Soft scene cues','轻柔场景提示音')}</label><label><input type="checkbox" disabled>${tr('Dialogue audio · no voice track; subtitles are always available','对白声音 · 暂无配音，始终提供字幕')}</label><label><input type="checkbox" data-playback-motion ${this.reduce?'checked':''}>${tr('Still scenes / reduced motion','静态场景／减少动态')}</label></details><details class="scene-transcript"><summary>${tr('Read the still-scene transcript','阅读静态场景文字')}</summary>${this.beats.map(beat=>`<p><strong>${E(beat.speaker)}</strong> · ${E(beat.text)}</p>`).join('')}</details></div>`;
  this.root=element.firstElementChild;this.onClick=e=>{const key=e.target.closest('[data-playback]')?.dataset.playback;if(key==='skip'){this.stopAudio();this.clock.finish('skipped');}if(key==='pause'){if(this.reduce||this.failed)return;this.manualPaused=!this.manualPaused;this.manualPaused?this.clock.pause():this.clock.play();this.manualPaused?this.stopAudio():this.startAudio();this.lastFrame=0;this.updateControls();this.schedule();}if(key==='replay'){if(this.failed)return;this.lastFrame=0;this.clock.replay();this.media?.seek(0);this.manualPaused=false;this.updateControls();this.schedule();}};
